<?php
session_start();if(empty($_SESSION["admin"])){header("Location: index.php");exit;}
require_once "../config/conexion.php";
if($_SERVER["REQUEST_METHOD"]==="POST"){
 $id=(int)($_POST["pedido_id"]??0);
 try{$conexion->beginTransaction();$q=$conexion->prepare("SELECT mesa_id FROM pedidos WHERE id=? AND estado<>'Pagado' FOR UPDATE");$q->execute([$id]);$mesa=$q->fetchColumn();if($mesa){$conexion->prepare("UPDATE pedidos SET estado='Pagado' WHERE id=?")->execute([$id]);$conexion->prepare("UPDATE mesas SET estado='Libre' WHERE id=?")->execute([$mesa]);}$conexion->commit();header("Location: cobros.php?ok=1");exit;}
 catch(Throwable $e){if($conexion->inTransaction())$conexion->rollBack();$error="No se pudo completar el cobro.";}
}
$pedidos=$conexion->query("SELECT p.id,p.total,p.fecha,m.numero AS mesa,c.nombre AS cliente FROM pedidos p JOIN mesas m ON m.id=p.mesa_id LEFT JOIN clientes c ON c.id=p.cliente_id WHERE p.estado<>'Pagado' ORDER BY p.fecha")->fetchAll(PDO::FETCH_ASSOC);
?>
<!DOCTYPE html><html lang="es"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Cobros | El Puerto</title><link rel="stylesheet" href="../assets/css/estilos.css"></head><body class="pixel-bg"><header class="topbar"><a class="pixel-logo" href="panel.php">EL PUERTO <small>CHECKOUT</small></a><nav><a href="panel.php">Panel</a><a href="index.php?salir=1">Salir</a></nav></header><main class="wrap"><p class="eyebrow">CAJA / CUENTAS ABIERTAS</p><h1>Cobro de pedidos</h1><p class="intro">Revisa el total de la mesa y marca el pedido como pagado. Al completar el cobro, la mesa vuelve a estar libre.</p><?php if(isset($_GET["ok"])):?><p class="notice">Cobro registrado. La mesa está libre.</p><?php endif;?><?php if(isset($error)):?><p class="notice"><?= $error ?></p><?php endif;?><div class="table-box"><table><thead><tr><th>Pedido</th><th>Mesa</th><th>Cliente</th><th>Fecha</th><th>Total</th><th>Acción</th></tr></thead><tbody><?php foreach($pedidos as $p):?><tr><td>#<?= $p["id"] ?></td><td>Mesa <?= $p["mesa"] ?></td><td><?= htmlspecialchars($p["cliente"]??"Sin registrar") ?></td><td><?= $p["fecha"] ?></td><td>$<?= number_format($p["total"],2) ?></td><td><form method="POST" onsubmit="return confirm('¿Confirmar que el pedido fue pagado?')"><input type="hidden" name="pedido_id" value="<?= $p["id"] ?>"><button class="small-btn">REGISTRAR PAGO</button></form></td></tr><?php endforeach;?><?php if(!$pedidos):?><tr><td colspan="6">No hay pedidos pendientes de cobro.</td></tr><?php endif;?></tbody></table></div></main></body></html>